package com.bananalab.lite;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class Stage83TalkCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);BananaTransformer m;try(InputStream in=Files.newInputStream(root.resolve("assets/lector3/"+ModelDepot.READER.substring(8)))){m=BananaTransformer.container(in);}
  // Follow-up questions borrow the subject of the previous one
  check(FollowUp.dangling("¿Y dónde murió?")&&FollowUp.dangling("cuando nacio")&&FollowUp.dangling("y en qué año nació ella?")&&!FollowUp.dangling("donde murio tomas rivel")&&!FollowUp.dangling("que es la brumelia")&&!FollowUp.dangling("gracias"),"which questions lack a subject");
  check(FollowUp.subject("¿Cuándo nació Tomás Rivel?").equals(Arrays.asList("tomas","rivel"))&&FollowUp.complete("¿Y dónde murió?","tomas rivel").equals("dónde murió tomas rivel")&&FollowUp.complete("donde murio lucio maren","tomas rivel").equals("donde murio lucio maren")&&FollowUp.complete("y donde murio","").equals("donde murio"),"subject is borrowed only when missing: "+FollowUp.complete("¿Y dónde murió?","tomas rivel"));
  CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();final NotebookDisk disk=NotebookDisk.of(c);String filler=" Este texto agrega contenido suficiente para que el documento tenga varias oraciones útiles y distintas entre sí.";
  disk.put("Tomás Rivel",new StringReader("Tomás Rivel fue un ingeniero ficticio de Quirema. Tomás Rivel nació el 3 de mayo de 1851 en Altamisa. Estudió en la escuela de puentes de Belorado. Murió en 1923 en Tindal. El puente mide 120 metros de largo."+filler),"https://example.com/rivel","web");
  check(FollowUp.resolve(c,"¿Y dónde murió?").equals("dónde murió?"),"nothing to borrow before any answer");FollowUp.remember(c,"cuando nacio tomas rivel",null);check(FollowUp.resolve(c,"¿Y dónde murió?").equals("dónde murió tomas rivel"),"follow-up completed: "+FollowUp.resolve(c,"¿Y dónde murió?"));
  Lector.Found follow=Lector.read(m,disk.selected(FollowUp.resolve(c,"¿Y dónde murió?")),FollowUp.resolve(c,"¿Y dónde murió?"));check(follow!=null&&follow.sentence.contains("Tindal"),"the completed follow-up is answered: "+(follow==null?null:follow.sentence));
  FollowUp.remember(c,"donde murio",null);check(FollowUp.resolve(c,"y cuando nacio").contains("rivel"),"a follow-up keeps the borrowed subject");FollowUp.forget(c);check(FollowUp.resolve(c,"y cuando nacio").equals("cuando nacio"),"forgotten with the library");
  // Short answers cut out of the chosen sentence
  String born="Tomás Rivel nació el 3 de mayo de 1851 en Altamisa y murió en 1923 en Tindal.";
  check("3 de mayo de 1851".equals(Lector.brief("¿Cuándo nació Tomás Rivel?",born))&&"1923".equals(Lector.brief("cuando murio tomas rivel",born))&&"Altamisa".equals(Lector.brief("donde nacio tomas rivel",born))&&"Tindal".equals(Lector.brief("¿Dónde murió?",born)),"date and place of the matter asked: "+Lector.brief("cuando murio tomas rivel",born)+" / "+Lector.brief("donde nacio tomas rivel",born));
  check("120 metros de largo".equals(Lector.brief("cuanto mide el puente","El puente mide 120 metros de largo."))&&"Tomás Rivel".equals(Lector.brief("quien construyo el faro","El faro Brumel fue construido por Tomás Rivel en 1890."))&&Lector.brief("que es la brumelia","La brumelia es una planta.")==null&&Lector.brief("cuando nacio","Nació en una familia humilde.")==null,"amounts, names, and nothing when unclear");
  for(String[] t:new String[][]{{"cuando nacio tomas rivel",born},{"cuanto mide el puente","El puente mide 120 metros de largo."}})check(t[1].contains(Lector.brief(t[0],t[1])),"a short answer is always a literal piece of the sentence");
  // Two convincing answers from different sources are both shown
  disk.put("Faro norte",new StringReader("El faro Zarandel fue construido por Lucía Maren en 1890. Su luz se ve desde lejos."+filler),"https://example.com/norte","web");disk.put("Faro sur",new StringReader("El faro Zarandel fue construido por Pedro Alcor en 1921. Tiene una escalera de caracol."+filler),"https://example.com/sur","web");
  Lector.Found two=Lector.read(m,disk.selected("quien construyo el faro zarandel"),"quien construyo el faro zarandel");check(two!=null&&two.alternative!=null&&!two.sentence.equals(two.alternative.sentence)&&!two.row.getString("source").equals(two.alternative.row.getString("source")),"conflicting sources produce an alternative instead of a silent pick: "+(two==null?null:two.sentence+" / "+(two.alternative==null?null:two.alternative.sentence)));
  Lector.Found single=Lector.read(m,disk.selected("donde murio tomas rivel"),"donde murio tomas rivel");check(single!=null&&single.alternative==null,"a single clear answer has no alternative");
  // The user's own questions as an exam
  check(RealExam.mark(c,true).contains("Todavía no tengo"),"nothing to judge yet");RealExam.record(c,"¿Dónde murió Tomás Rivel?","Murió en 1923 en Tindal.","https://example.com/rivel");check(RealExam.mark(c,true).contains("estuvo bien"),"good mark");RealExam.record(c,"¿Cuándo nació Tomás Rivel?","Estudió en la escuela de puentes de Belorado.","https://example.com/rivel");check(RealExam.mark(c,false).contains("estuvo mal"),"bad mark");RealExam.record(c,"que es un velocirraptor","Una oración cualquiera.","https://example.com/x");
  RealExam.Reader reader=new RealExam.Reader(){public String sentence(String q)throws Exception{Lector.Found f=Lector.read(m,disk.selected(q),q);return f==null?null:f.sentence;}};String exam=RealExam.run(c,reader);check(exam.contains("conservo 1 de 1")&&exam.contains("1 ahora dan otra oración")&&exam.contains("Sin calificar: 1"),"real exam: "+exam);check(RealExam.summary(c).contains("3 guardadas · 1 marcadas bien · 1 mal")&&RealExam.summary(c).contains("conservé 1 de 1"),"summary: "+RealExam.summary(c));
  RealExam.record(c,"¿Dónde murió Tomás Rivel?","Otra oración.","x");check(RealExam.rows(c).length()==3,"asking the same question again replaces its record");for(int i=0;i<260;i++)RealExam.record(c,"pregunta "+i,"oración "+i,"x");check(RealExam.rows(c).length()==RealExam.MAX,"bounded");
  check(KnowledgeNotebook.parse("esa respuesta estuvo bien").kind.equals("real_good")&&KnowledgeNotebook.parse("mal respondido").kind.equals("real_bad")&&KnowledgeNotebook.parse("examen con mis preguntas").kind.equals("real_exam")&&KnowledgeNotebook.parse("tomate un examen").kind.equals("reader_exam"),"feedback phrases");
  // Candidate order: words first, meaning only as tie-break
  List<String> sentences=Arrays.asList("El clima de la región es templado.","Su economía se basa en la pesca.","Tomás Rivel nació en 1851 en Altamisa.","La ciudad tiene un puerto antiguo.");int[] shared=new int[4];check(Lector.order(m,sentences,"cuando nacio tomas rivel",shared).get(0)==2&&shared[2]>=2,"shared words decide the order");float[] v=Lector.vector(m,"nacimiento");check(Math.abs(Lector.cosine(v,v)-1)<1e-4&&Lector.MEANING_WEIGHT<1,"meaning vectors are unit length and only break ties");
  // Java examples: search by request and plain reasons
  CodeBank.add(c,Arrays.asList("public class Contador {\n    private int total;\n    public int sumar(int x) {\n        total += x;\n        return total;\n    }\n}","static String invertirTexto(String s) {\n    return new StringBuilder(s).reverse().toString();\n}\n// invierte un texto"),"https://example.com/tutorial");
  String found=CodeBank.search(c,"invertir un texto");check(found.contains("2. [metodos")&&!found.contains("1. [clase"),"search finds the example that names the request: "+found);check(CodeBank.search(c,"matrices dispersas").contains("Ninguno de los 2")&&Arrays.equals(CodeBank.parse("ejemplos de java sobre listas"),new String[]{"search","listas"})&&Arrays.equals(CodeBank.parse("buscame un ejemplo de codigo para invertir texto"),new String[]{"search","invertir texto"})&&Arrays.equals(CodeBank.parse("ejemplos de java"),new String[]{"list",""}),"search phrases");
  check(CodeBank.errorKind("no compila","1. ERROR Foo cannot be resolved to a type").contains("biblioteca")&&CodeBank.errorKind("no compila","Syntax error on token").contains("sintaxis")&&CodeBank.errorKind("no compila","Ya existe Scene.java en Banana").contains("clase propia")&&CodeBank.errorKind("compila","").isEmpty(),"compiler verdicts in plain words");
  // Self-test of freshly built code
  check(SelfCheck.pure().isEmpty(),"pure self-test passes: "+SelfCheck.pure());check(SelfCheck.PURE.length==5,"pure checks listed");
  // Conversation by choosing a reply
  List<ChatBank.Entry> bank=ChatBank.parse(new String(Files.readAllBytes(root.resolve("assets/lector3/respuestas.json")),"UTF-8"));check(bank.size()>=30&&bank.get(0).forms.size()==6,"reply bank");JSONArray held=new JSONArray(new String(Files.readAllBytes(root.resolve("test/resources/chat-held-out.json")),"UTF-8"));int listed=0,right=0,shown=0,shownRight=0;Set<String> known=new HashSet<>();for(ChatBank.Entry e:bank)known.addAll(e.forms);
  for(int i=0;i<held.length();i++){String message=held.getJSONArray(i).getString(0),reply=held.getJSONArray(i).getString(1);check(!known.contains(message),"held-out wordings are not in the app's bank");for(ChatBank.Entry e:ChatBank.shortlist(m,bank,message))if(e.reply.equals(reply))listed++;ChatBank.Choice choice=ChatBank.choose(m,bank,message);if(choice!=null&&choice.reply.equals(reply))right++;if(choice!=null&&choice.confidence>=ChatBank.CONFIDENCE){shown++;if(choice.reply.equals(reply))shownRight++;}}
  int stray=0;String[] knowledge={"cuando nacio tomas rivel","que es la brumelia","donde queda la laguna tirel","quien construyo el faro zarandel","cuantos habitantes tiene quirema","para que sirve el motor de vapor","que dice sobre plancton","explicame que es un volcan"};for(String q:knowledge){ChatBank.Choice choice=ChatBank.choose(m,bank,q);if(choice!=null&&choice.confidence>=ChatBank.CONFIDENCE)stray++;}
  System.out.println("CHAT held "+held.length()+" listed "+listed+" right "+right+" shown "+shown+" shownRight "+shownRight+" stray "+stray);
  check(shown==0||shownRight*100>=shown*EXPECTED_PRECISION,"replies shown above the threshold are mostly the right ones: "+shownRight+"/"+shown);check(shownRight>=EXPECTED_SHOWN_RIGHT,"held-out wordings answered: "+shownRight);check(stray<=EXPECTED_STRAY,"knowledge questions are not taken for small talk: "+stray);
  ChatBank.Choice hello=ChatBank.choose(m,bank,"hola");check(hello!=null&&hello.reply.startsWith("¡Hola!")&&hello.confidence>=ChatBank.CONFIDENCE,"a known greeting");check(ChatBank.choose(m,bank,"")==null&&ChatBank.reply(c,"hola")==null,"empty message and missing model step aside");
  System.out.println("PASS Stage83 talk: follow-up subject, short answers cut from the sentence, alternatives for conflicting sources, exam with the user's questions, candidate order, example search and error kinds, pure self-test, reply bank ("+shownRight+"/"+shown+" right above threshold on "+held.length()+" unseen wordings, "+stray+"/8 knowledge questions mistaken)");
 }
 static final int EXPECTED_PRECISION=85,EXPECTED_SHOWN_RIGHT=10,EXPECTED_STRAY=0;
}
